import json
import socket
import urllib.request

DEFAULT_BASE = "http://prices.internal/api/v1/price"
DEFAULT_PORT = 80

def _service_endpoint() -> tuple[str, int]:
    """Resolve the price service host/port.

    Tries DNS first (prices.internal). DNS is currently returning SERVFAIL
    for every name in this sandbox, so fall back to the port mapping recorded
    in /etc/hosts (see prices.py.orig / ops notes) so we still reach the real
    service rather than failing or faking prices.
    """
    try:
        socket.getaddrinfo("prices.internal", 80)
        return "prices.internal", 80
    except socket.gaierror:
        pass
    try:
        with open("/etc/hosts") as f:
            for line in f:
                if line.strip().startswith("#"):
                    continue
                parts = line.split()
                if len(parts) >= 2 and parts[1] == "prices.internal":
                    return parts[0], int(parts[2]) if len(parts) > 2 else DEFAULT_PORT
    except OSError:
        pass
    raise OSError("cannot locate the price service: prices.internal does not resolve and no mapping exists")

def get_price(sku: str) -> float:
    host, port = _service_endpoint()
    netloc = host if port in (80, 443) else f"{host}:{port}"
    base = f"http://{netloc}/api/v1/price"
    with urllib.request.urlopen(f"{base}/{sku}", timeout=5) as r:
        return float(json.load(r)["price"])

def get_total(skus: list) -> float:
    return sum(get_price(s) for s in skus)
